-- Add two reaction categories (dev.to parity): fire and exploding-head.
--
-- Prisma's autogenerated migration also emitted SQL to drop the searchVector
-- index and its "default", because it does not understand the tsvector
-- generated column (Unsupported type). That SQL was wrong — a generated column
-- has no default — and has been removed. Only the enum additions are needed.

ALTER TYPE "ReactionCategory" ADD VALUE IF NOT EXISTS 'FIRE';
ALTER TYPE "ReactionCategory" ADD VALUE IF NOT EXISTS 'EXPLODING_HEAD';
